package com.erp.oa.attendance.leave;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.math.BigDecimal;
import java.time.*;
import org.junit.jupiter.api.*;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.erp.approval.api.RemoteApprovalService;
import com.erp.approval.api.domain.ApprovalStartRequest;
import com.erp.common.core.context.SecurityContextHolder;
import com.erp.common.security.shop.ShopScopeService;
import com.erp.oa.service.BusinessFeatureGate;
import com.erp.oa.attendance.leave.AttendanceLeaveModels.*;
import com.erp.oa.attendance.leave.AttendanceLeaveRequests.SaveDraft;
import com.erp.oa.attendance.leave.balance.AttendanceLeaveQuotaServiceTest.Harness;
class AttendanceLeaveQuotaLifecycleTest
{
 Harness h; AttendanceLeaveService service; AttendanceLeaveApprovalOutboxService outbox; AttendanceLeaveApprovalAfterCommitTrigger trigger;
 @BeforeEach void setup(){TransactionSynchronizationManager.setActualTransactionActive(true);TransactionSynchronizationManager.setCurrentTransactionIsolationLevel(java.sql.Connection.TRANSACTION_READ_COMMITTED);SecurityContextHolder.setUserId("11");SecurityContextHolder.setUserName("synthetic");h=new Harness();h.request.reason="synthetic leave";h.request.rowVersion=0L;h.type.allowCrossDay=true;h.type.payPolicy="PAID";h.type.approvalRequired=true;when(h.leaves.selectLeaveTypeForUpdate(1L)).thenReturn(h.type);when(h.leaves.selectLeaveTypeById(1L)).thenReturn(h.type);when(h.leaves.selectActiveEmployeeNameInShop(11L,20L)).thenReturn("synthetic");when(h.leaves.insertLeaveSegment(any())).thenReturn(1);when(h.leaves.updateLeaveDraft(any())).thenReturn(1);when(h.leaves.insertLeaveRequest(any())).thenAnswer(i->{LeaveRequest r=i.getArgument(0);r.leaveRequestId=10L;when(h.leaves.selectLeaveRequestById(10L)).thenReturn(r);when(h.leaves.selectLeaveRequestByIdForUpdate(10L)).thenReturn(r);when(h.leaves.selectLeaveRequestByClientRequestId(eq(11L),eq(20L),anyString())).thenReturn(r);return 1;});when(h.leaves.markLeaveSubmitting(eq(10L),anyString(),anyLong(),anyInt(),anyString())).thenReturn(1);ShopScopeService scope=mock(ShopScopeService.class);when(scope.resolveRequiredShopDept(20L)).thenReturn(20L);when(scope.resolveShopDeptName(20L)).thenReturn("synthetic shop");outbox=mock(AttendanceLeaveApprovalOutboxService.class);trigger=mock(AttendanceLeaveApprovalAfterCommitTrigger.class);ApprovalOutbox queued=new ApprovalOutbox();queued.outboxId=70L;when(outbox.enqueue(any(),any(),anyString())).thenReturn(queued);service=new AttendanceLeaveService(h.leaves,mock(AttendanceLeaveAttachmentStorage.class),outbox,trigger,mock(RemoteApprovalService.class),scope,mock(BusinessFeatureGate.class),Clock.fixed(Instant.parse("2026-09-12T00:00:00Z"),ZoneOffset.UTC),h.service);}
 @AfterEach void clear(){SecurityContextHolder.remove();TransactionSynchronizationManager.clear();}
 SaveDraft body(boolean edit){SaveDraft b=new SaveDraft();b.leaveRequestId=edit?10L:null;b.leaveTypeId=1L;b.rowVersion=edit?0L:null;b.startTime=h.request.startTime;b.endTime=h.request.endTime;b.reason=h.request.reason;b.requestedDays=BigDecimal.ONE;return b;}
 @Test void realSaveStoresConfirmedDaysSeparatelyFromClockSpan(){LeaveRequest result=service.saveDraft(body(false),20L);assertThat(result.requestedDays).isEqualByComparingTo("1");assertThat(result.totalMinutes).isEqualTo(1440);assertThat(result.quotaUnits).isEqualTo(420_000_000L);assertThat(result.quotaStatus).isEqualTo("NOT_RESERVED");assertThat(h.allocations).isEmpty();}
 @Test void omissionOnSameTypeCannotBypassStoredPolicyChange(){h.service.freezeDraft(h.request,h.type,null);h.match.rule.version=2;h.match.rule.config.minutesPerDay=new BigDecimal("480");assertThatThrownBy(()->service.saveDraft(body(true),20L)).hasMessageContaining("政策或单位已变化");verify(h.leaves,never()).updateLeaveDraft(any());}
 @Test void changedAmountIsFrozenBeforeMapperCanMutateCaller(){SaveDraft b=body(false);when(h.leaves.selectActiveEmployeeNameInShop(11L,20L)).thenAnswer(i->{b.requestedDays=new BigDecimal("2");return "synthetic";});LeaveRequest saved=service.saveDraft(b,20L);assertThat(saved.requestedDays).isEqualByComparingTo("1");assertThat(saved.quotaUnits).isEqualTo(420_000_000L);}
 @Test void exactCreateKeyReplaySurvivesPolicyChangeWithoutNewWrite(){SaveDraft b=body(false);b.clientRequestId="quota-create-001";LeaveRequest first=service.saveDraft(b,20L);h.match.rule.version=2;assertThat(service.saveDraft(b,20L)).isSameAs(first);verify(h.leaves,times(1)).insertLeaveRequest(any());assertThat(first.quotaPolicySnapshot.ruleVersion).isEqualTo(1);b.requestedDays=new BigDecimal("2");assertThatThrownBy(()->service.saveDraft(b,20L)).hasMessageContaining("CLIENT_REQUEST_ID_REUSED");}
 @Test void annualCannotUseDisabledBalanceOrApprovalToAutoApprove(){h.type.balanceRequired=false;h.type.approvalRequired=false;h.service.freezeDraft(h.request,h.type,null);service.submit(10L,0L,20L);assertThat(h.request.status).isEqualTo("SUBMITTING");assertThat(h.allocations).hasSize(2);verify(h.leaves,never()).markLeaveAutoApproved(anyLong(),anyString(),anyLong(),anyString());var capture=org.mockito.ArgumentCaptor.forClass(ApprovalStartRequest.class);verify(outbox).enqueue(eq(h.request),capture.capture(),anyString());assertThat(capture.getValue().getVariables()).containsEntry("requestedDays","1").containsEntry("quotaUnits","420000000").containsKey("quotaPolicySnapshot");}
 @Test void pendingRepeatReturnsOriginalWithoutAnotherAllocation(){h.reserve();h.request.approvalInstanceId=90L;service.submit(10L,999L,20L);assertThat(h.allocations).hasSize(2);verifyNoInteractions(outbox,trigger);}
 @Test void policyDriftAtSubmitLeavesNoReservationOrOutbox(){h.service.freezeDraft(h.request,h.type,null);h.type.rowVersion=2L;assertThatThrownBy(()->service.submit(10L,0L,20L)).hasMessageContaining("政策或单位已变化");assertThat(h.allocations).isEmpty();verifyNoInteractions(outbox,trigger);}
 @Test void oldQuotaDraftMustBeExplicitlySavedBeforeSubmitting(){assertThatThrownBy(()->service.submit(10L,0L,20L)).hasMessageContaining("历史草稿");assertThat(h.allocations).isEmpty();}

 @Test void mixedTypeAllowsExplicitUnitChangeWithSameFrozenPolicy(){h.type.unitMode="MIXED";h.service.freezeDraft(h.request,h.type,null);SaveDraft b=body(true);b.requestedDays=null;LeaveRequest saved=service.saveDraft(b,20L);assertThat(saved.quotaPolicySnapshot.amountUnit).isEqualTo("MINUTES");assertThat(saved.quotaUnits).isEqualTo(1440_000_000L);b.rowVersion=saved.rowVersion;b.requestedDays=BigDecimal.ONE;b.quotaPolicySnapshot=h.service.copyPolicy(saved.quotaPolicySnapshot);saved=service.saveDraft(b,20L);assertThat(saved.quotaPolicySnapshot.amountUnit).isEqualTo("DAYS");assertThat(saved.quotaUnits).isEqualTo(420_000_000L);}
 @Test void mixedAmountChangeStillRejectsRuleDrift(){h.type.unitMode="MIXED";h.service.freezeDraft(h.request,h.type,null);h.match.rule.version=2;SaveDraft b=body(true);b.requestedDays=null;assertThatThrownBy(()->service.saveDraft(b,20L)).hasMessageContaining("政策或单位已变化");verify(h.leaves,never()).updateLeaveDraft(any());}

 @Test void policyPreviewRecoversCurrentPolicyWithoutWritingOldDraftOrGranting(){h.service.freezeDraft(h.request,h.type,null);String original=h.request.quotaPolicyJson;h.match.rule.version=2;h.match.rule.config.minutesPerDay=new BigDecimal("480");SaveDraft b=body(true);var preview=service.previewPolicy(10L,b,20L);assertThat(preview.quotaPolicySnapshot.ruleVersion).isEqualTo(2);assertThat(preview.quotaUnits).isEqualTo(480_000_000L);assertThat(preview.rowVersion).isEqualTo(0L);assertThat(preview.userId).isEqualTo(11L);assertThat(preview.shopId).isEqualTo(20L);assertThat(h.request.quotaPolicyJson).isEqualTo(original);assertThat(h.request.quotaUnits).isEqualTo(420_000_000L);assertThat(h.allocations).isEmpty();assertThat(h.ledger).isEmpty();assertThat(mockingDetails(h.core).getInvocations()).noneMatch(i->i.getMethod().getName().equals("prepareForLeave"));verify(h.leaves,never()).updateLeaveDraft(any());verify(h.leaves,never()).insertLeaveRequest(any());b.quotaPolicySnapshot=preview.quotaPolicySnapshot;assertThat(service.saveDraft(b,20L).quotaUnits).isEqualTo(480_000_000L);}
 @Test void previewRequiresOwnedEditableExactDraftVersion(){SaveDraft b=body(true);b.rowVersion=1L;assertThatThrownBy(()->service.previewPolicy(10L,b,20L)).hasMessageContaining("VERSION");b.rowVersion=0L;h.request.status="PENDING";assertThatThrownBy(()->service.previewPolicy(10L,b,20L)).hasMessageContaining("EDITABLE");h.request.status="DRAFT";h.request.userId=12L;assertThatThrownBy(()->service.previewPolicy(10L,b,20L)).hasMessageContaining("NOT_OWNED");assertThat(h.allocations).isEmpty();}
 @Test void previewEchoesFrozenProposedInputAndDoesNotMutateCallersDraft(){SaveDraft b=body(true);when(h.leaves.selectLeaveTypeForUpdate(1L)).thenAnswer(i->{b.requestedDays=new BigDecimal("2");b.reason="changed after start";return h.type;});var result=service.previewPolicy(10L,b,20L);assertThat(result.requestedDays).isEqualByComparingTo("1");assertThat(result.reason).isEqualTo("synthetic leave");assertThat(result.startTime).isEqualTo(h.request.startTime);assertThat(h.request.requestedDays).isEqualByComparingTo("1");assertThat(h.request.quotaPolicyJson).isNull();}
}
